function flattenObject(obj, parentKey = '') {
    let flatObject = {};
    for (let key in obj) {
        let newKey = parentKey ? `${parentKey}[${key}]` : key;
        if (typeof obj[key] === 'object' && obj[key] !== null) {
            Object.assign(flatObject, flattenObject(obj[key], newKey));
        } else {
            flatObject[newKey] = obj[key];
        }
    }
    return flatObject;
}

