def longest_subarray_sum_zero(arr):
    # Dictionary to store the first occurrence of a prefix sum
    prefix_sum_indices = {}
    max_length = 0
    current_sum = 0

    for i in range(len(arr)):
        current_sum += arr[i]

        if arr[i] == 0 and max_length == 0:
            max_length = 1

        if current_sum == 0:
            max_length = i + 1

        if current_sum in prefix_sum_indices:
            max_length = max(max_length, i - prefix_sum_indices[current_sum])
        else:
            prefix_sum_indices[current_sum] = i

    return max_length

# Example usage
arr = [3, 4, -7, 3, 1, 3, 1, -4, -2, -2]
print("Length of the longest subarray with sum 0:", longest_subarray_sum_zero(arr))
```
