std::vector<int> generateFibonacci(int n) {
    std::vector<int> fibonacciSeries;
    if (n <= 0) return fibonacciSeries;

    fibonacciSeries.push_back(0);
    if (n == 1) return fibonacciSeries;

    fibonacciSeries.push_back(1);

    int nextFib = 0;
    for (int i = 2; i < n; ++i) {
        nextFib = fibonacciSeries[i - 1] + fibonacciSeries[i - 2];
        fibonacciSeries.push_back(nextFib);
    }

    return fibonacciSeries;
}

