std::unordered_map<char, int> findCharFrequency(const std::string& str) {
    std::unordered_map<char, int> frequencyMap;
    for (char ch : str) {
        frequencyMap[ch]++;
    }
    return frequencyMap;
}

int main() {
    std::string testString = "hello world";
    auto frequency = findCharFrequency(testString);

    for (const auto& pair : frequency) {
        std::cout << "Character: " << pair.first << ", Frequency: " << pair.second << std::endl;
    }

    return 0;
}
